var LENSES=[
 {k:'Psychology',t:'Studying the mind scientifically',w:'Barnard College of Columbia University. B.A. in Psychology, minor in Economics.',d:'I learned to investigate human thoughts and behavior through scientific methods.',g:'Over time, I realized that rather than simply studying the human mind, I wanted to tell stories about it.'},
 {k:'Storytelling',t:'Telling stories about the mind',w:'New York University. M.A. in Media, Culture, and Communication.',d:'For my graduation project I wrote and directed a short film exploring mental health and self-care among young adults.',g:'It taught me to communicate complicated human experience through narrative and visual design.'},
 {k:'Technology',t:'Rebuilding a website',w:'Bank of China U.S.A., corporate communications.',d:'I coordinated a 3,000-hour website rebuild. Drawing on the perspective-taking skills I had developed through psychology, I worked with different teams and technical vendors to understand their needs and move the project forward. I also taught myself HTML so our team could update the website\'s content.',g:'This was the part of my job I enjoyed most, and it inspired me to study computer science.'},
 {k:'Computer science',t:'Learning to program',w:'Graduate study in computer science.',d:'I earned A grades in my courses:',l:['Python programming','Discrete structures','Data structures and systems applications in C'],g:'I gradually realized that although I enjoyed coding, I still didn\'t know what I wanted to create with it.'},
 {k:'Clinical research',t:'Returning to the question',w:"Columbia University Postbaccalaureate Premedical Program, then the Department of Child and Adolescent Psychiatry at the Shanghai Mental Health Center.",d:'Hoping to get closer to the brain itself, I went back to Columbia for two years of pre-medical coursework, and spent over 200 hours volunteering in hospitals. The turning point came in the year of research that followed.',l:['Conducted more than 310 MINI-KID clinical assessments','Took part in psychological, cognitive and neurodevelopmental assessments','Supported MRI and EEG data collection','Taught myself multivariable logistic regression and led the data analysis in Python and SPSS','Wrote the Results and Discussion sections of our manuscript'],g:'I saw how technology could support psychological assessment and research while largely remaining a tool for established methods. It made me wonder whether technology could play a more active role in supporting mental health and improving people\'s lives.'},
 {k:'Building',t:'Deciding to build something myself',w:'An app, an exploratory paper, and a game built in Godot.',d:'My first app, designed to help people recognize obsessive-compulsive patterns, was coded entirely by AI. It worked, but to me it was a black box: I couldn\'t fix it or tell whether it was safe. That led me to write Where Should AI Stop?, an independent exploratory paper on the balance between AI capabilities and human judgment, and to apply its principles to Into the Stars, a game designed to help people relax before sleep. I directed the design, reviewed the AI-generated plans and code, and built and tested it myself. When AI couldn\'t solve a key interface problem, I designed the solution myself.',g:'I realized that I wanted to work with AI, not simply depend on it. I also realized that I still lacked the technical depth to bring more complex ideas to life.'}
];
var lensEl=$('#lenses'),lensPanel=$('#lensPanel');
function drawLens(i){
  $$('button',lensEl).forEach(function(b,j){b.setAttribute('aria-pressed',j===i)});
  var L=LENSES[i];
  lensPanel.innerHTML='<div><h3>'+L.t+'</h3><p class="where">'+L.w+'</p></div><div class="what">'+(L.d?'<p>'+L.d+'</p>':'')+(L.l?'<ul>'+L.l.map(function(x){return '<li>'+x+'</li>'}).join('')+'</ul>':'')+'<p class="gave">'+L.g+'</p></div>';
}
LENSES.forEach(function(L,i){var b=document.createElement('button');b.type='button';b.textContent=L.k;b.addEventListener('click',function(){drawLens(i)});lensEl.appendChild(b)});
drawLens(4);

