 conv:{lane:'Interface',n:'Conversational interfaces',d:'Mobile-first screens in which conversation is one element among structured, purpose-built views.',fam:'A separate entrance and private space for each family member.',rel:'One person can begin alone, with no partner account.',pro:'Reminders to leave out anything that identifies a patient.',learn:'React, TypeScript, front-end architecture, accessibility'},
 ctx:{lane:'Agent',n:'Context-aware assistance',d:'Model calls that receive only the context the current task and the current permissions allow.',fam:'Explanations specific to a condition, with no invented diagnoses.',rel:'Reflection without advice on whether to stay or go.',pro:'Awareness of clinical roles, settings and vocabulary.',learn:'LLM APIs, prompt design, structured outputs'},
 state:{lane:'Agent',n:'Structured conversational state',d:'An explicit model of where a conversation stands, stored as data and not left implicit in a transcript.',fam:'State is kept per person and never merged without consent.',rel:'Tracks what has been clarified and what remains the user\'s decision.',pro:'Separates a personal concern, a work-related one, and a search for care.',learn:'State machines, data modeling, memory design'},
 flow:{lane:'Agent',n:'Scoped agent workflows',d:'Narrow agents with defined steps, tools and stopping conditions, using explicit logic wherever predictability matters.',fam:'Guides a clinician-approved exercise without altering it.',rel:'Care navigation with a small, bounded set of clarifying questions.',pro:'Helps a clinician articulate what expertise they need.',learn:'Tool calling, workflow orchestration, algorithms'},
 consent:{lane:'Trust',n:'Identity, consent and privacy',d:'Authentication, role-based permissions and consent records that decide what may move between people.',fam:'Sharing is per item, between named family members, and reversible.',rel:'The right not to participate is part of the data model.',pro:'A sponsor can pay without being able to see.',learn:'Authentication, authorization, database security, encryption'},
